({
    packetReads: lab.packetPrediction(),
    completeFrame: lab.frame("default", "clean", "baseline", "empty"),
    blindChoice: lab.selection("dynamic", 3, 35)
})

["empty", "mixed", "full"].map(kind => {
    const row = lab.packetCosts("opening", kind);
    return {kind, packets:row.packetsPerBlock, unit:row.unit,
        scalar:row.schedules.scalar.cycles_per_packet_median,
        minimum:row.schedules.empty.cycles_per_packet_median};
})

["pie", "empty", "full"].map(plan => {
    const row = simd.executions(plan+"-row", plan+"-opening", "scalar-lane-load");
    return {plan, imageSHA:row.imageSHA, executedLoads:row.executions};
})

({
    checkedPlanar: lab.physicsPair("particle", 128, "guarded-soa-scalar", "guarded-soa-pie"),
    oneTickIncludingConversion: lab.physicsPair("particle", 128, "aos-scalar", "convert-pie-roundtrip"),
    identicalContactOrder: lab.physicsPair("contact", 128, "grouped-scalar", "grouped-pie")
})

(() => {
    const trials = lab.scores.cases;
    const misses = trials.filter(t => t.predicted !== t.best);
    return {cases:trials.length, winners:trials.length-misses.length,
        distinctPredictions:[...new Set(trials.map(t=>t.predicted))],
        misses:misses.map(t=>({n:t.n, reach:t.reach, excessPercent:t.regretPct})),
        laneLoads:["pie","empty","full"].map(k=>
            simd.executions(k+"-row", k+"-opening", "scalar-lane-load").executions)};
})()

(() => {
    const clean = lab.frames.filter(r=>r.phase===0);
    const pairs = clean.filter(r=>r.arm===0).map(base=>{
        const candidates = clean.filter(r=>r.fixture===base.fixture && r.block===base.block && r.arm===1);
        if (candidates.length!==1) throw Error("missing or duplicate candidate");
        return {fixture:base.fixture, block:base.block, savedUs:base.us-candidates[0].us};
    });
    return {pairs:pairs.length, wins:pairs.filter(p=>p.savedUs>0).length,
        opening:pairs.filter(p=>p.fixture==="default").map(p=>p.savedUs)};
})()
